mapper.insert:
INSERT INTO ${type.table}
(
    NO
    , VACATION_NO
    , WRITER_NO
    , FIRST_APPLY_NO
    , MID_APPLY_NO
    , LAST_APPLY_NO
    , START_TIME
    , FINISH_TIME
    , CONTENT
    , WRITE_DATE
)
VALUES
(
    ${type.sequence}.NEXTVAL
    , #{doc.vacationNo}
    , #{doc.writerNo}
    , #{doc.firstApplyNo}
    , #{doc.midApplyNo}
    , #{doc.lastApplyNo}
    , TO_DATE(#{doc.startTime}, 'YYYY-MM-DD')
    , TO_DATE(#{doc.finishTime}, 'YYYY-MM-DD')
    , #{doc.content}
    , SYSDATE
)

mapper.select:
SELECT 
FROM () A

WHERE A.DOC_TYPE = #{docType}
AND A.NO = #{no}
AND A.DEL_YN = 'N'

SELECT * FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY A.WRITE_DATE DESC, A.NO DESC) AS RNUM,

    FROM () A

    WHERE A.DEL_YN = 'N'
    AND A.WRITER_NO = #{memberNo}

)
WHERE RNUM BETWEEN #{startRow} AND #{lastRow}

SELECT * FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY A.WRITE_DATE ASC, A.NO ASC) AS RNUM,

    FROM () A

    WHERE 

)
WHERE RNUM BETWEEN #{startRow} AND #{lastRow}

mapper.update:
UPDATE ${type.table}
SET CATEGORY_NO = 2, DOCUMENT_DATE = SYSDATE
WHERE NO = #{no}
AND CATEGORY_NO = 1
AND FIRST_STATUS = 2 AND MID_STATUS = 2 AND LAST_STATUS = 2

UPDATE ${type.table}
SET CATEGORY_NO = 3, DOCUMENT_DATE = SYSDATE, REJECTION = #{rejection}
WHERE NO = #{no}
AND CATEGORY_NO = 1

UPDATE ${type.table}
SET DEL_YN = 'Y'
WHERE NO = #{no}
AND WRITER_NO = #{memberNo}
AND DEL_YN = 'N'
